function renderValidation(){const result=validate();$('validityPill').textContent=result.valid?'Policy structurally valid':result.errors.length+' issue'+(result.errors.length===1?'':'s');$('validityPill').className='validity-pill '+(result.valid?'valid':'invalid');const rows=result.errors.slice(0,5).map(item=>'<div class="check-row bad"><span>!</span><div><strong>'+esc(item.code)+'</strong><small>'+esc(item.message)+'</small></div></div>');if(!rows.length)rows.push('<div class="check-row good"><span>✓</span><div><strong>Graph + schema</strong><small>Required blocks compile to a fail-closed policy draft.</small></div></div>');for(const item of result.warnings.slice(0,2))rows.push('<div class="check-row warn"><span>i</span><div><strong>'+esc(item.code)+'</strong><small>'+esc(item.message)+'</small></div></div>');$('validationChecks').innerHTML=rows.join('');const p=result.policy;$('compileSummary').innerHTML='<div><span>Policy version</span><strong>v'+p.version+'</strong></div><div><span>Default action</span><strong>'+p.defaultAction.toUpperCase()+'</strong></div><div><span>Wallets</span><strong>'+p.wallets.length+'</strong></div><div><span>Contract methods</span><strong>'+p.contracts.reduce((n,c)=>n+(c.methods?.length||0),0)+'</strong></div><div><span>State threshold</span><strong>'+p.protocolState.threshold+' / '+p.protocolState.trustedKeys.length+'</strong></div><div><span>Trace quorum</span><strong>'+p.simulation.quorum+' / '+p.simulation.sources.length+'</strong></div><div class="wide"><span>7702 posture</span><strong>'+(p.simulation.eip7702.allowAuthorizationList||p.simulation.eip7702.allowDelegatedWallet?'PINNED OPT-IN':'DENY')+'</strong></div>';$('policyJson').textContent=JSON.stringify(p,null,2);return result}
function render(){renderPalette();renderCanvas();renderInspector();renderValidation();const wallet=graph.nodes.find(n=>n.type==='wallet');$('policyName').value=wallet?.config.name||'Untitled Keybound policy'}
function applyViewport(){$('canvasWorld').style.transform='translate('+viewport.x+'px,'+viewport.y+'px) scale('+viewport.scale+')';$('zoomReadout').textContent=Math.round(viewport.scale*100)+'%'}
