function setZoom(next,clientX,clientY){const rect=$('canvas').getBoundingClientRect(),x=clientX??rect.left+rect.width/2,y=clientY??rect.top+rect.height/2,before=worldPoint(x,y);viewport.scale=Math.min(1.7,Math.max(.25,next));viewport.x=x-rect.left-before.x*viewport.scale;viewport.y=y-rect.top-before.y*viewport.scale;applyViewport();drawMinimap()}
