function connectionEnd(event){window.removeEventListener('pointermove',connectionMove);const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-input]');if(target&&target.dataset.input!==connectFrom&&!graph.edges.some(edge=>edge.source===connectFrom&&edge.target===target.dataset.input)){graph.edges.push({id:id('edge'),source:connectFrom,target:target.dataset.input});persist()}connectFrom=null;ghostPoint=null;render()}
function download(){const result=renderValidation(),blob=new Blob([JSON.stringify(result.policy,null,2)+'\\n'],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=(result.policy.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'keybound-policy')+'.json';document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(result.valid?'Validated draft exported.':'Draft exported with '+result.errors.length+' issue(s).')}
